def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    for r in range(h - 1):
        for c in range(w - 1):
            if not all(grid[i][j] == 2
                       for i in (r, r + 1)
                       for j in (c, c + 1)):
                continue

            # Corner marker coordinates and the color each outward ray receives.
            corners = {
                "ul": (r - 1, c - 1),
                "ur": (r - 1, c + 2),
                "bl": (r + 2, c - 1),
                "br": (r + 2, c + 2),
            }
            source_for = {"ul": "bl", "ur": "ul", "bl": "br", "br": "ur"}
            colors = {}
            for dest, src in source_for.items():
                sr, sc = corners[src]
                if 0 <= sr < h and 0 <= sc < w and grid[sr][sc] != 0:
                    colors[dest] = grid[sr][sc]

            directions = {
                "ul": (-1, -1),
                "ur": (-1, 1),
                "bl": (1, -1),
                "br": (1, 1),
            }
            for corner, (sr, sc) in corners.items():
                if corner not in colors or not (0 <= sr < h and 0 <= sc < w):
                    continue
                dr, dc = directions[corner]
                i, j = sr, sc
                while 0 <= i < h and 0 <= j < w:
                    out[i][j] = colors[corner]
                    i += dr
                    j += dc

    return out
